    Bug 1941552 - Fix Overflowed constant in Convert_whitespace. r=BenC

    CID: 1639764

    If starting with 0, after -- we have 4294967295 as next value

    Differential Revision: https://phabricator.services.mozilla.com/D234299

diff --git a/mailnews/mime/src/mimetpfl.cpp b/mailnews/mime/src/mimetpfl.cpp
index 5eb50f2373d..61ea31b7174 100644
--- a/mailnews/mime/src/mimetpfl.cpp
+++ b/mailnews/mime/src/mimetpfl.cpp
@@ -557,15 +557,18 @@ static void Convert_whitespace(const char16_t a_current_char,
     number_of_space = 0;
   }

-  while (number_of_nbsp--) {
-    a_out_string.AppendLiteral("&nbsp;");
+  if (number_of_nbsp != 0) {
+    while (number_of_nbsp--) {
+      a_out_string.AppendLiteral("&nbsp;");
+    }
   }

-  while (number_of_space--) {
-    // a_out_string += ' '; gives error
-    a_out_string.Append(' ');
+  if (number_of_space != 0) {
+    while (number_of_space--) {
+      // a_out_string += ' '; gives error
+      a_out_string.Append(' ');
+    }
   }
-
   return;
 }
